-- Create "inventory_resources" table
CREATE TABLE "inventory_resources" ("facility_id" uuid NOT NULL, "id" uuid NOT NULL DEFAULT gen_random_uuid(), "kind" text NOT NULL, "name" text NOT NULL, "capacity" integer NOT NULL, "enabled" boolean NOT NULL DEFAULT false, PRIMARY KEY ("facility_id", "id"), CONSTRAINT "inventory_resources_facility_id_id_capacity_key" UNIQUE ("facility_id", "id", "capacity"), CONSTRAINT "inventory_resources_facility_id_id_kind_key" UNIQUE ("facility_id", "id", "kind"), CONSTRAINT "inventory_resources_facility_id_fkey" FOREIGN KEY ("facility_id") REFERENCES "facilities" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "inventory_resources_capacity_valid" CHECK (capacity > 0), CONSTRAINT "inventory_resources_kind_valid" CHECK (kind = ANY (ARRAY['sauna'::text, 'tent'::text])), CONSTRAINT "inventory_resources_name_valid" CHECK (((length(name) >= 1) AND (length(name) <= 200)) AND (length(btrim(name)) > 0)));
-- Modify "product_offerings" table
ALTER TABLE "product_offerings" ADD CONSTRAINT "product_offerings_kind_unique" UNIQUE ("facility_id", "product_id", "kind");
-- Create "inventory_product_resources" table
CREATE TABLE "inventory_product_resources" ("facility_id" uuid NOT NULL, "product_id" uuid NOT NULL, "product_kind" text NOT NULL, "resource_id" uuid NOT NULL, "resource_kind" text NOT NULL, PRIMARY KEY ("facility_id", "product_id", "resource_id"), CONSTRAINT "inventory_product_resources_facility_id_product_id_resource_key" UNIQUE ("facility_id", "product_id", "resource_id", "product_kind"), CONSTRAINT "inventory_product_offering_fk" FOREIGN KEY ("facility_id", "product_id", "product_kind") REFERENCES "product_offerings" ("facility_id", "product_id", "kind") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "inventory_product_resource_fk" FOREIGN KEY ("facility_id", "resource_id", "resource_kind") REFERENCES "inventory_resources" ("facility_id", "id", "kind") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "inventory_product_resource_kind_valid" CHECK (((product_kind = ANY (ARRAY['private_sauna'::text, 'shared_sauna'::text])) AND (resource_kind = 'sauna'::text)) OR ((product_kind = ANY (ARRAY['day_tent'::text, 'overnight_tent'::text])) AND (resource_kind = 'tent'::text))));
-- Create "inventory_claims" table
CREATE TABLE "inventory_claims" ("facility_id" uuid NOT NULL, "id" uuid NOT NULL DEFAULT gen_random_uuid(), "product_id" uuid NOT NULL, "product_kind" text NOT NULL, "resource_id" uuid NOT NULL, "resource_capacity" integer NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "seat_slots" int4range NOT NULL, "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(), "released_at" timestamptz NULL, PRIMARY KEY ("facility_id", "id"), CONSTRAINT "inventory_claim_no_overlap" EXCLUDE USING gist ("facility_id" WITH =, "resource_id" WITH =, (tstzrange(starts_at, ends_at, '[)'::text)) WITH &&, "seat_slots" WITH &&) WHERE (released_at IS NULL), CONSTRAINT "inventory_claim_capacity_fk" FOREIGN KEY ("facility_id", "resource_id", "resource_capacity") REFERENCES "inventory_resources" ("facility_id", "id", "capacity") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "inventory_claim_mapping_fk" FOREIGN KEY ("facility_id", "product_id", "resource_id", "product_kind") REFERENCES "inventory_product_resources" ("facility_id", "product_id", "resource_id", "product_kind") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "inventory_claim_period_valid" CHECK (isfinite(starts_at) AND isfinite(ends_at) AND (starts_at < ends_at)), CONSTRAINT "inventory_claim_release_valid" CHECK (isfinite(created_at) AND ((released_at IS NULL) OR (isfinite(released_at) AND (released_at >= created_at)))), CONSTRAINT "inventory_claim_seats_valid" CHECK ((NOT isempty(seat_slots)) AND (((product_kind = 'shared_sauna'::text) AND (NOT lower_inf(seat_slots)) AND (NOT upper_inf(seat_slots)) AND (lower(seat_slots) >= 0) AND (upper(seat_slots) <= resource_capacity) AND (((upper(seat_slots))::bigint - (lower(seat_slots))::bigint) = 1)) OR ((product_kind = ANY (ARRAY['private_sauna'::text, 'day_tent'::text, 'overnight_tent'::text])) AND lower_inf(seat_slots) AND upper_inf(seat_slots)))));
